'use strict';
const KEY='forma-public-personal-v1', TODAY=localDate(new Date());
function localDate(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function dateObj(s){return new Date(s+'T12:00:00')}
function shift(s,n){let d=dateObj(s);d.setDate(d.getDate()+n);return localDate(d)}
function dayIndex(s){return (dateObj(s).getDay()+6)%7}
function fmtDate(s,long=false){return dateObj(s).toLocaleDateString('ru-RU',{day:'numeric',month:long?'long':'short',...(long?{weekday:'long'}:{})})}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
const round=n=>Math.round(n),num=(n,d=0)=>Number(n).toLocaleString('ru-RU',{maximumFractionDigits:d}), clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const ICONS={home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',food:'<path d="M5 3v7m4-7v7M3 3v5a4 4 0 0 0 8 0V3M7 12v9M17 3c-3 4-3 8 2 8V3v18"/>',gym:'<path d="M6 5v14M3 8v8M18 5v14M21 8v8M6 12h12"/>',chart:'<path d="M4 3v17h17M7 15l4-5 4 3 5-8"/>',book:'<path d="M12 5v16M3 4c3-1 6 0 9 2 3-2 6-3 9-2v15c-3-1-6 0-9 2-3-2-6-3-9-2z"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>',left:'<path d="m15 5-7 7 7 7"/>',right:'<path d="m9 5 7 7-7 7"/>',check:'<path d="m5 12 4 4L19 6"/>',plus:'<path d="M12 4v16M4 12h16"/>',drop:'<path d="M12 2c-3 5-7 9-7 13a7 7 0 0 0 14 0c0-4-4-8-7-13z"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',close:'<path d="m5 5 14 14M19 5 5 19"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',walk:'<circle cx="14" cy="4" r="2"/><path d="m12 8-3 5-4 1m7-6 4 5 4 1M9 13l4 2 2 6M12 8l-1 8-4 5"/>',scale:'<path d="M5 5h14l3 16H2z"/><path d="M8 8a5 5 0 0 1 8 0m-4 3 2-3"/>',edit:'<path d="m4 16 12-12 4 4L8 20H4zM13 7l4 4"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2m-3-7-2 2M7 17l-2 2M5 5l2 2m10 10 2 2"/>'};
function ico(n){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[n]||ICONS.food}</svg>`}
const defaults={version:1,profile:{age:'',height:'',baseline:'',kcal:2000,protein:160,fat:65,steps:7500,water:2250,dayA:2,dayB:5,club:'club1',clubNames:{club1:'Зал 1',club2:'Зал 2'},start:TODAY,notes:'',foodsNote:'Без мяты. Другие ограничения можно указать здесь.'},days:{},measurements:[],shopping:{},completed:{},notes:{}};
let state,storageOK=true;
try{const raw=JSON.parse(localStorage.getItem(KEY)||'null');state=raw&&raw.version===1?{...defaults,...raw,profile:{...defaults.profile,...raw.profile}}:structuredClone(defaults)}catch{state=structuredClone(defaults);storageOK=false}
let DATA,view='home',selected=TODAY,workout='A',timerEnd=0,timerInterval=null;
try{timerEnd=Number(localStorage.getItem(KEY+'-timer'))||0}catch{}
const root=document.getElementById('app'),modal=document.getElementById('modal');
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;document.querySelectorAll('.save-status').forEach(x=>x.textContent='Сохранено на этом устройстве')}catch{storageOK=false;toast('Не удалось сохранить. Экспортируй резервную копию.')}}
let toastTimeout;function toast(s){const t=document.getElementById('toast');t.textContent=s;t.classList.add('visible');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>t.classList.remove('visible'),3500)}
function day(s=selected){return state.days[s]||={meals:{},water:0,steps:'',sets:{},custom:[],cardio:''}}
function targetCarbs(){return Math.max(0,round((state.profile.kcal-state.profile.protein*4-state.profile.fat*9)/4))}
function recipe(id){return DATA.recipes.find(r=>r.id===id)}
function mealFor(slot,s=selected){const logged=day(s).meals[slot];const r=recipe(logged?.id||DATA.menus[dayIndex(s)][slot]);return {...r,foods:r.foods.map(([f,g],i)=>[f,logged?.grams?.[i]??g])}}
function macros(foods){return [0,1,2,3].map(i=>foods.reduce((n,[f,g])=>n+(DATA.foods[f]?.[i]||0)*g/100,0))}
function sum(vs){return vs.reduce((a,v)=>a.map((n,i)=>n+(v[i]||0)),[0,0,0,0])}
function planned(s=selected){return sum([0,1,2,3].map(i=>macros(mealFor(i,s).foods)))}
function eaten(s=selected){const d=day(s);return sum([...Array.from({length:4},(_,i)=>d.meals[i]?.done?macros(mealFor(i,s).foods):[0,0,0,0]),...(d.custom||[]).map(c=>[c.kcal,c.p,c.f,c.c])])}
function trainingDay(s=selected){const d=dayIndex(s);return d===Number(state.profile.dayA)?'A':d===Number(state.profile.dayB)?'B':null}
function weekNumber(){return Math.max(1,Math.floor((dateObj(selected)-dateObj(state.profile.start))/86400000/7)+1)}
const NAV=[['home','Сегодня','home'],['meals','Питание','food'],['training','Зал','gym'],['progress','Прогресс','chart'],['guide','Гайд','book']];
function nav(){document.getElementById('sidebar').innerHTML=`<div class="brand">ФОРМА<span>/</span></div><p class="brand-sub">ТВОЯ ЛИЧНАЯ ПРОГРАММА</p><div class="side-links">${NAV.map(([v,t,i])=>`<button class="nav-btn ${view===v?'active':''}" data-nav="${v}">${ico(i)}${t}</button>`).join('')}</div><div class="side-bottom"><strong>${num(state.profile.kcal)} ккал в день</strong>${state.profile.baseline?esc(state.profile.age)+' лет · '+esc(state.profile.height)+' см · старт '+num(state.profile.baseline,1)+' кг':'Личные параметры — в профиле'}<br><button class="nav-btn" data-nav="settings">${ico('settings')}Мой профиль</button><small>Данные в этом браузере</small></div>`;document.getElementById('mobile-nav').innerHTML=NAV.map(([v,t,i])=>`<button class="nav-btn ${view===v?'active':''}" data-nav="${v}">${ico(i)}<span>${t}</span></button>`).join('');document.getElementById('header').innerHTML=`<div class="crumb">Моя программа / <b>${NAV.find(n=>n[0]===view)?.[1]||'Мой профиль'}</b></div><div class="header-right"><span class="save-status">${storageOK?'Сохранение на устройстве':'Хранилище недоступно'}</span><button class="icon-btn" data-nav="settings" aria-label="Открыть профиль">${ico('settings')}</button><div class="avatar">Я</div></div>`}
function dateControl(){return `<div class="date-control"><button class="icon-btn" data-action="date-prev" aria-label="Предыдущий день">${ico('left')}</button><input type="date" id="selected-date" aria-label="Дата программы" value="${selected}"><button class="icon-btn" data-action="date-next" aria-label="Следующий день">${ico('right')}</button></div>`}
function head(title,desc,dates=true){return `<div class="page-head"><div><div class="eyebrow">${esc(fmtDate(selected,true))}</div><h1>${title}</h1><p class="subtitle">${desc}</p></div>${dates?dateControl():''}</div>`}
function weekStrip(){const first=shift(selected,-dayIndex(selected));return `<div class="week-strip">${Array.from({length:7},(_,i)=>{let d=shift(first,i);return `<button class="day-btn ${d===selected?'active':''}" data-date="${d}">${['ПН','ВТ','СР','ЧТ','ПТ','СБ','ВС'][i]}<b>${dateObj(d).getDate()}</b>${trainingDay(d)?'<i title="День зала"></i>':''}</button>`}).join('')}</div>`}
function macroCards(){let vals=eaten(),t=[state.profile.kcal,state.profile.protein,state.profile.fat,targetCarbs()];return `<div class="grid four">${['Калории','Белок','Жиры','Углеводы'].map((label,i)=>`<div class="card"><div class="stat-top">${i===0?ico('food'):''}${label}</div><div class="stat-num">${num(round(vals[i]))} <span>/ ${num(t[i])} ${i===0?'ккал':'г'}</span></div><div class="track"><i style="width:${clamp(vals[i]/Math.max(t[i],1)*100,0,100)}%"></i></div><small>${vals[i]>t[i]?'Выше ориентира на '+num(round(vals[i]-t[i])):'Осталось '+num(round(t[i]-vals[i]))} ${i===0?'ккал':'г'}</small></div>`).join('')}</div>`}
function miniMeal(i){let r=mealFor(i),m=macros(r.foods),done=!!day().meals[i]?.done;return `<div class="meal-line ${done?'meal-done':''}"><div class="meal-icon">${ico(i===0?'sun':'food')}</div><div class="meal-copy"><small>${r.type}</small><h3>${esc(r.name)}</h3><small>${round(m[0])} ккал <span>· Б ${round(m[1])} г</span></small></div><button class="check-btn ${done?'checked':''}" data-action="toggle-meal" data-slot="${i}" aria-label="${done?'Снять отметку':'Съедено'}: ${esc(r.type)}" aria-pressed="${done}">${done?ico('check'):ico('plus')}</button></div>`}
function home(){const d=day(),tr=trainingDay(),mealCount=[0,1,2,3].filter(i=>d.meals[i]?.done).length;return head('Твой план на сегодня','Питание и движение в ритме обычной жизни.')+`${!state.profile.baseline?'<div class="info-strip">Заполни параметры в профиле. Они сохранятся только на твоём устройстве. <button class="text-link" data-nav="settings">Мой профиль</button></div>':''}<section class="hero"><div class="hero-copy"><div class="eyebrow">ПЕРСОНАЛЬНЫЙ ПЛАН · НЕДЕЛЯ ${weekNumber()}</div><h2>Снижаем жир.<br>Сохраняем силу.</h2><p>Среда и выходной — фуллбоди с акцентом на верх тела. В остальные дни — привычная ходьба и восстановление.</p><div class="hero-metrics"><div><b>${num(state.profile.kcal)}</b><small>ккал на старте</small></div><div><b>${state.profile.protein} г</b><small>белка в день</small></div><div><b>2</b><small>силовые в неделю</small></div></div><button class="btn lime small" data-nav="${tr?'training':'meals'}">${tr?'Открыть тренировку '+tr:'Моё меню на день'}${ico('arrow')}</button></div><div class="hero-photo" role="img" aria-label="Тарелка с разнообразной едой"></div></section><div class="section-head"><h2>Питание за день</h2><span class="tag">${mealCount} из 4 приёмов</span></div>${macroCards()}<div class="grid layout-main" style="margin-top:22px"><section class="card"><div class="flex between"><h3>Твоё меню</h3><button class="text-link" data-nav="meals">Порции и замены ${ico('right')}</button></div>${[0,1,2,3].map(miniMeal).join('')}${d.custom?.length?`<div class="tip">Дополнительно: ${d.custom.map(c=>esc(c.name)).join(', ')}. Эти калории уже учтены.</div>`:''}</section><div class="grid"><section class="card"><div class="flex between"><h3>${tr?'Сегодня зал':'День восстановления'}</h3>${ico(tr?'gym':'walk')}</div><div class="training-banner"><div class="mini-label">${tr?'ФУЛЛБОДИ '+tr:'ПРИВЫЧНЫЙ ТЕМП'}</div><strong>${tr?'Верх тела + умеренно ноги':'Ходьба и обычная активность'}</strong><p class="muted" style="font-size:12px;margin:7px 0 12px">${tr?'Около 60–80 минут с разминкой и кардио. Первые недели не тренируемся до отказа.':'Ориентир шагов — удобная цель, а не обязанность идти через усталость.'}</p><button class="btn small soft" data-nav="${tr?'training':'progress'}">${tr?'Перейти к упражнениям':'Записать замеры'}${ico('arrow')}</button></div><div class="inline-input" style="margin-top:16px"><label style="flex:1">Шаги за день<input type="number" id="daily-steps" min="0" max="100000" inputmode="numeric" placeholder="Например, 7500" value="${esc(d.steps)}"></label><button class="icon-btn" data-action="save-steps" aria-label="Сохранить шаги">${ico('check')}</button></div></section><section class="card"><div class="flex between"><h3>Вода и напитки</h3>${ico('drop')}</div><div class="mini-num">${num(d.water/1000,2)} <span class="muted" style="font-size:14px">/ ${num(state.profile.water/1000,2)} л</span></div><div class="water-cups">${Array.from({length:8},(_,i)=>`<i class="${d.water>=state.profile.water*(i+1)/8?'full':''}"></i>`).join('')}</div><div class="flex"><button class="btn small soft" data-action="water" data-add="250">+250 мл</button><button class="btn small outline" data-action="water" data-add="-250">−250</button></div><p class="tip">Пей по жажде. Чай и кофе тоже считаются. Медицинские ограничения жидкости важнее ориентира.</p></section></div></div><p class="long-note" style="margin-top:22px">Показатели питания рассчитываются по отмеченным блюдам и твоим порциям. Пока блюдо не отмечено, оно входит только в план, а не в съеденное.</p>`}
function mealCard(i){let r=mealFor(i),m=macros(r.foods),done=!!day().meals[i]?.done;return `<article class="card meal-card"><div class="meal-card-head"><div><div class="eyebrow">${r.type}</div><h3>${esc(r.name)}</h3><div class="macro-mini" style="margin-top:8px">≈${round(m[0])} ккал · Б ${round(m[1])} · Ж ${round(m[2])} · У ${round(m[3])} г</div></div><button class="check-btn ${done?'checked':''}" data-action="toggle-meal" data-slot="${i}" aria-label="Отметить ${r.type}" aria-pressed="${done}">${done?ico('check'):ico('plus')}</button></div><div class="ingredients">${r.foods.map(([f,g],j)=>`<div class="ingredient"><span class="food-name">${esc(f)}</span><input type="number" aria-label="Граммы: ${esc(f)}" min="0" max="2000" step="1" inputmode="numeric" data-portion="${i}" data-food="${j}" value="${g}"><span class="muted">г</span></div>`).join('')}</div><div class="method">${esc(r.method)}</div><div class="meal-footer"><button class="btn small outline" data-action="swap" data-slot="${i}">${ico('edit')}Заменить блюдо</button><span class="completion">${done?'Учтено в дневнике':'План на день'}</span></div></article>`}
function meals(){let t=planned(),d=day();return head('Твоё питание','Семь вариантов дня около 2000 ккал. Блюда и порции можно менять.')+weekStrip()+`<div class="nutrition-total"><div><small>План выбранного дня</small><br><strong>${round(t[0])} <span>ккал</span></strong></div><span><b>Б ${round(t[1])}</b> / Ж ${round(t[2])} / У ${round(t[3])} г</span><button class="btn small soft" data-action="shopping">${ico('food')}Список покупок</button></div><div class="info-strip">Граммовки мяса и рыбы — сырые, круп — сухие, фасоли — готовые. Калории примерные: сверяй этикетки. В меню нет мяты. Проверь состав покупных продуктов и сохрани другие ограничения в профиле.</div><div class="grid two">${[0,1,2,3].map(mealCard).join('')}</div><div class="section-head"><h2>Дополнительно съедено</h2><button class="btn small soft" data-action="custom-meal">${ico('plus')}Добавить</button></div>${(d.custom||[]).length?d.custom.map((c,i)=>`<div class="card flex between" style="margin-bottom:10px"><div><strong>${esc(c.name)}</strong><div class="macro-mini">${c.kcal} ккал · Б ${c.p} / Ж ${c.f} / У ${c.c} г</div></div><button class="icon-btn" data-action="remove-custom" data-index="${i}" aria-label="Удалить запись">${ico('close')}</button></div>`).join(''):`<div class="empty">Здесь можно учесть десерт, напиток, соус или другую еду вне меню.</div>`}<p class="long-note" style="margin-top:17px">На дни зала не нужно автоматически добавлять калории с тренажёра или часов. Банан и йогурт из меню можно перенести ближе к занятию. Рецепты рассчитаны на одну порцию.</p>`}
const EXERCISES={
legpress:{name:'Жим ногами в тренажёре',muscle:'Квадрицепсы и ягодицы',reps:'10–15',sets:2,rest:120,alternatives:['Жим ногами горизонтальный','Жим ногами под углом'],tech:'Настрой сиденье так, чтобы таз и спина сохраняли опору. Стопы всей поверхностью на платформе. Сгибай ноги в комфортной амплитуде без отрыва таза. Не запирай колени и не задерживай дыхание. Не ищи максимальную глубину любой ценой.'},
chest:{name:'Жим от груди в тренажёре',muscle:'Грудь, трицепс',reps:'10–12',sets:3,rest:120,alternatives:['Горизонтальный жим сидя','Жим в рычажном тренажёре'],tech:'Рукояти примерно на уровне середины груди. Спина на опоре, шея в комфортном нейтральном положении. Плавно выжимай, без рывка и болезненного растяжения плеч. Локти не разводи предельно в стороны.'},
row:{name:'Горизонтальная тяга с опорой',muscle:'Средняя часть спины',reps:'10–12',sets:3,rest:120,alternatives:['Тяга с упором грудью','Горизонтальная блочная тяга'],tech:'Предпочти опору грудью, если она доступна и удобна. Тяни локти назад без запрокидывания головы и раскачки корпуса. Своди лопатки умеренно, не пожимай плечами. Рукоять и хват должны быть комфортны для рук.'},
legcurl:{name:'Сгибание ног сидя',muscle:'Задняя поверхность бедра',reps:'12–15',sets:2,rest:90,alternatives:['Сгибание ног сидя','Сгибание ног лёжа'],tech:'Совмести ось коленного сустава с осью тренажёра, валик расположи по инструкции тренажёра. Сгибай плавно, удерживай таз на сиденье. Остановись при боли в колене или спине.'},
lateral:{name:'Отведение рук в тренажёре',muscle:'Средняя часть плеч',reps:'12–15',sets:2,rest:90,alternatives:['Отведение рук сидя в тренажёре','Отведение руки в нижнем блоке'],tech:'Начни с минимального комфортного веса. Поднимай руки без пожимания плечами и напряжения шеи. Не поднимай выше комфортного уровня плеч. Если тренажёр неудобен или появляются симптомы, пропусти упражнение.'},
biceps:{name:'Сгибание рук в тренажёре',muscle:'Бицепс',reps:'10–15',sets:2,rest:90,alternatives:['Сгибание рук в тренажёре','Сгибание рук в нижнем блоке'],tech:'Настрой опору, не выпрямляй локоть насильно. Сохраняй запястье в удобном положении и одинаково контролируй обе стороны. Не повышай вес при боли или заметном ограничении рук.'},
triceps:{name:'Разгибание рук на блоке',muscle:'Трицепс',reps:'10–15',sets:2,rest:90,alternatives:['Разгибание рук с канатом','Разгибание рук с прямой рукоятью'],tech:'Локти рядом с корпусом. Разгибай руки без раскачки и сильного наклона головы. Выбери канат или рукоять, при которой нет боли в кисти и локте.'},
pulldown:{name:'Тяга верхнего блока к груди',muscle:'Широчайшие, бицепс',reps:'10–12',sets:3,rest:120,alternatives:['Тяга верхнего блока нейтральным хватом','Вертикальная тяга в рычажном тренажёре'],tech:'Зафиксируй бёдра. Тяни рукоять перед собой к верхней части груди без рывка и запрокидывания головы. Не тяни за голову. Выбирай комфортную ширину хвата, не стремись насильно коснуться груди.'},
pec:{name:'Сведение рук в тренажёре',muscle:'Грудные мышцы',reps:'12–15',sets:2,rest:90,alternatives:['Сведение рук «бабочка»','Лёгкий жим от груди вместо сведения'],tech:'Рукояти или опоры настрой под комфортную амплитуду. Не уводи плечи далеко назад. Своди руки плавно, без сильного напряжения шеи. Можно пропустить при дискомфорте в плече.'}
};
const ROUTINES={A:['legpress','chest','row','legcurl','lateral','biceps','triceps'],B:['legpress','pulldown','chest','legcurl','row','lateral','triceps']};
const CLUBS={club1:'Зал 1',club2:'Зал 2'};
function club(){return day().club||state.profile.club||'club1'}
function setKey(id){return workout+'-'+club()+'-'+id}
function completedKey(){return selected+'-'+workout+'-'+club()}
function setCount(id){return weekNumber()<=2?2:EXERCISES[id].sets}
function setData(id,i){const key=setKey(id);const d=day();d.sets[key]||=[];return d.sets[key][i]||={kg:'',reps:'',rir:'',done:false}}
function previousSet(id,i){let dates=Object.keys(state.days).filter(s=>s<selected).sort().reverse();for(let dt of dates){let r=state.days[dt].sets?.[setKey(id)]?.[i];if(r?.done){const oldVariant=state.days[dt].variants?.[setKey(id)]||EXERCISES[id].alternatives[0],currentVariant=day().variants?.[setKey(id)]||EXERCISES[id].alternatives[0];if(oldVariant===currentVariant)return r}}return null}
function setRow(id,i){const s=setData(id,i),prev=previousSet(id,i);return `<div class="set-row ${s.done?'done':''}"><b>${i+1}</b><input type="number" min="0" max="1000" step="0.5" inputmode="decimal" aria-label="${esc(EXERCISES[id].name)}: вес, подход ${i+1}" placeholder="${prev?esc(prev.kg):'кг'}" value="${esc(s.kg)}" data-set="${id}" data-i="${i}" data-field="kg"><input type="number" min="1" max="100" step="1" inputmode="numeric" aria-label="Повторения, подход ${i+1}" placeholder="${prev?esc(prev.reps):'повт.'}" value="${esc(s.reps)}" data-set="${id}" data-i="${i}" data-field="reps"><input type="number" min="0" max="10" step="1" inputmode="numeric" aria-label="Запас повторений, подход ${i+1}" placeholder="3" value="${esc(s.rir)}" data-set="${id}" data-i="${i}" data-field="rir"><button class="check-btn ${s.done?'checked':''}" data-action="set-done" data-ex="${id}" data-index="${i}" aria-label="Завершить подход ${i+1}" aria-pressed="${s.done}">${ico('check')}</button></div>`}
function exerciseCard(id,i){const e=EXERCISES[id];let variant=day().variants?.[setKey(id)]||e.alternatives[0];return `<details class="card exercise" ${i===0?'open':''} data-ex-detail="${id}"><summary><div class="ex-num">${String(i+1).padStart(2,'0')}</div><div class="ex-title"><h3>${esc(e.name)}</h3><p>${e.muscle} · ${setCount(id)} × ${e.reps} · отдых ${e.rest/60} мин</p></div><span class="tag">${day().sets[setKey(id)]?.filter(s=>s.done).length||0}/${setCount(id)}</span></summary><div class="details-body"><div class="technique">${e.tech}</div><label>Вариант тренажёра<select data-variant="${id}">${e.alternatives.map(a=>`<option ${variant===a?'selected':''}>${esc(a)}</option>`).join('')}</select></label><div class="set-row labels"><span>Подход</span><span>Вес, кг</span><span>Повторения</span><span>Запас (RIR)</span><span></span></div><div class="sets">${Array.from({length:setCount(id)},(_,i)=>setRow(id,i)).join('')}</div><p class="field-note">Серым показан прошлый завершённый подход в этом зале и варианте упражнения. Это подсказка, а не запись за сегодня. Если модель тренажёра другая, подбери вес заново.</p></div></details>`}
function training(){return head('Твой зал','Два зала, отдельные записи. Фуллбоди с акцентом на верх тела.')+`<div class="info-strip">Стартовая программа предполагает отсутствие противопоказаний к нагрузке. Если есть травмы или заболевания, уточни ограничения у врача, настройку тренажёров — с тренером. При боли, головокружении или необычной головной боли остановись.</div><label style="margin-top:18px;max-width:420px">Твой зал<select id="training-club">${Object.entries(CLUBS).map(([k,v])=>`<option value="${k}" ${club()===k?'selected':''}>${esc(v)}</option>`).join('')}</select></label><p class="field-note">Рабочие веса и прошлые подходы хранятся отдельно для каждого зала. На новой модели начни с подбора нагрузки заново.</p><div class="flex between wrap"><div class="workout-tabs"><button class="${workout==='A'?'active':''}" data-workout="A">A · ${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'][state.profile.dayA]}</button><button class="${workout==='B'?'active':''}" data-workout="B">B · ${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'][state.profile.dayB]}</button></div><span class="tag">Неделя ${weekNumber()} · ${weekNumber()<=2?'по 2 подхода, запас 3–4':'запас 2–3 повторения'}</span></div><div class="grid layout-main"><div><div class="timer"><div><div class="timer-value" id="timer-value">00:00</div><p>Таймер отдыха</p></div><div class="timer-actions"><button class="btn small lime" data-action="timer" data-seconds="90">90 сек</button><button class="btn small outline" style="color:white;border-color:#536355" data-action="timer" data-seconds="120">120</button><button class="icon-btn" style="color:white" data-action="timer-stop" aria-label="Остановить таймер">${ico('close')}</button></div></div>${ROUTINES[workout].map(exerciseCard).join('')}<div class="card"><h3>Кардио после силовой</h3><p class="muted" style="font-size:12px;margin:9px 0 15px">10–20 минут ходьбы на дорожке или велотренажёра в разговорном темпе. Начни с 10 минут, если устаёшь. Без необходимости держаться за поручни с усилием или напрягать шею.</p><label>Фактически, минут<input id="cardio-minutes" type="number" min="0" max="180" inputmode="numeric" value="${esc(day().cardio)}" placeholder="Например, 15"></label><button class="btn" data-action="finish-workout" style="width:100%;margin-top:12px">${ico('check')}Сохранить тренировку ${workout}</button>${state.completed[completedKey()]?`<p class="feedback">Тренировка сохранена в истории. Изменения подходов сохраняются отдельно.</p>`:''}</div></div><aside><section class="card"><div class="eyebrow">ПЕРЕД ПЕРВЫМ ПОДХОДОМ</div><h3>Разминка и настройка</h3><p class="long-note" style="margin-top:13px">5–8 минут спокойного кардио. Затем 1–2 лёгких разминочных подхода перед первым жимом и тягой. Они не входят в рабочие подходы. Попроси тренера настроить сиденья и опоры.</p><div class="tip">Не нужно занимать все 1 ч 40 мин–2 часа тяжёлой работой. Около 60–80 минут с паузами часто достаточно. Дольше — только если спокойно и удобно.</div></section><section class="card" style="margin-top:17px"><h3>Как выбрать вес</h3><p class="long-note" style="margin-top:12px">Начни с лёгкого веса. Последние повторения должны требовать усилия, но оставлять ${weekNumber()<=2?'3–4':'2–3'} повтора с хорошей техникой в запасе. RIR — сколько таких повторов ты ещё смог бы сделать.</p><p class="tip">Когда все подходы два занятия подряд достигают верхней границы повторений без симптомов и с нужным запасом, попробуй минимальный шаг тренажёра. Если шаг слишком велик, сохрани вес.</p></section><section class="card" style="margin-top:17px"><h3>Третий день?</h3><p class="long-note" style="margin-top:12px">Первые 4 недели придерживайся двух силовых. Если хочется двигаться чаще, добавь прогулку или 20–30 минут лёгкого кардио по переносимости. Третья тяжёлая тренировка требует оценки восстановления.</p></section></aside></div>`}
function weightStats(){const ms=state.measurements.filter(m=>Number.isFinite(m.weight)&&m.weight>0&&m.date<=selected).sort((a,b)=>a.date.localeCompare(b.date));const a=ms.filter(m=>m.date>=shift(selected,-6)),b=ms.filter(m=>m.date>=shift(selected,-13)&&m.date<=shift(selected,-7));const avg=x=>x.reduce((n,m)=>n+m.weight,0)/x.length;return{ms,latest:ms.at(-1),avg:a.length?avg(a):null,delta:a.length>=3&&b.length>=3?avg(a)-avg(b):null,a:a.length,b:b.length}}
function chart(ms){if(!ms.length)return `<div class="empty" style="margin-top:18px">${ico('chart')}<h3>Здесь появится твоя динамика</h3>Запиши первый утренний вес. График покажет только сохранённые тобой замеры.</div>`;let min=Math.min(...ms.map(m=>m.weight))-.5,max=Math.max(...ms.map(m=>m.weight))+.5;let first=dateObj(ms[0].date).getTime(),last=dateObj(ms.at(-1).date).getTime(),range=Math.max(last-first,86400000);const x=m=>45+(dateObj(m.date).getTime()-first)/range*690,y=m=>175-(m.weight-min)/(max-min)*145;return `<svg class="chart" viewBox="0 0 780 220" role="img" aria-label="График веса по сохранённым замерам">${[0,1,2,3].map(i=>{let v=min+(max-min)*i/3,yy=175-i*145/3;return `<line x1="45" y1="${yy}" x2="750" y2="${yy}" stroke="#e2e8dd"/><text x="0" y="${yy+4}">${num(v,1)}</text>`}).join('')}<polyline points="${ms.map(m=>`${x(m)},${y(m)}`).join(' ')}" fill="none" stroke="#2b6349" stroke-width="2.5"/>${ms.map(m=>`<circle cx="${x(m)}" cy="${y(m)}" r="4" fill="#2b6349"><title>${esc(fmtDate(m.date))}: ${m.weight} кг</title></circle>`).join('')}<text x="45" y="208">${esc(fmtDate(ms[0].date))}</text><text x="685" y="208">${esc(fmtDate(ms.at(-1).date))}</text></svg>`}
function progress(){let s=weightStats(),current=state.measurements.find(m=>m.date===selected),advice=s.delta===null?'Для сравнения недель нужны минимум 3 замера в каждой из двух последних недель. Сейчас данных недостаточно.':s.delta<-.9?'Снижение заметное. В первые недели часть изменения — вода. Если такой темп держится или падают силы, рассмотри +100–200 ккал.':s.delta<-.2?'Вес постепенно снижается. Если сон, голод и силовые в порядке, сохраняй текущие ориентиры.':'Не меняй калории из-за одной недели. Посмотри на талию и учёт еды за 2–3 недели, прежде чем корректировать план.';return head('Твой прогресс','Средняя масса и талия говорят больше, чем одно утреннее взвешивание.')+`<div class="grid three"><div class="card"><div class="stat-top">Последний замер до выбранной даты</div><div class="stat-num">${s.latest?num(s.latest.weight,1):'—'} <span>кг</span></div><small>${s.latest?fmtDate(s.latest.date):'Запиши первый утренний замер'}</small></div><div class="card"><div class="stat-top">Среднее за последние 7 дней</div><div class="stat-num">${s.avg?num(s.avg,2):'—'} <span>кг</span></div><small>Замеров: ${s.a} из 7</small></div><div class="card"><div class="stat-top">Изменение среднего за неделю</div><div class="stat-num">${s.delta!==null?(s.delta>0?'+':'')+num(s.delta,2):'—'} <span>кг</span></div><small>${s.delta===null?'Нужно больше наблюдений':'Сравнение двух последних недель'}</small></div></div><div class="card" style="margin-top:18px"><div class="flex between"><h3>Динамика массы</h3><span class="tag">Только твои записи</span></div>${chart(s.ms)}<div class="feedback">${advice}</div></div><section class="card" style="margin-top:18px"><h3>Новый замер · ${esc(fmtDate(selected))}</h3><form id="measure-form"><div class="measure-row"><label>Вес утром, кг<input type="number" name="weight" min="35" max="250" step="0.1" inputmode="decimal" required placeholder="Например, 89.2" value="${current?.weight??''}"></label><label>Талия, см · необязательно<input type="number" name="waist" min="40" max="200" step="0.5" inputmode="decimal" placeholder="На спокойном выдохе" value="${current?.waist??''}"></label><label>Сон, часов · необязательно<input type="number" name="sleep" min="0" max="24" step="0.5" inputmode="decimal" placeholder="Например, 7.5" value="${current?.sleep??''}"></label><button class="btn" type="submit">Сохранить</button></div><label style="margin-top:12px">Самочувствие / заметка<textarea name="note" rows="2" maxlength="600" placeholder="Голод, усталость, силовые, особенности дня">${esc(current?.note||'')}</textarea></label></form><p class="field-note">Масса — после туалета, до еды. Талия — раз в неделю в одном месте. Повторное сохранение заменит запись выбранной даты.</p></section><div class="grid two" style="margin-top:18px"><section class="card"><h3>История замеров</h3>${state.measurements.length?`<table class="measure-table"><thead><tr><th>Дата</th><th>кг</th><th>Талия</th><th></th></tr></thead><tbody>${[...state.measurements].sort((a,b)=>b.date.localeCompare(a.date)).map(m=>`<tr><td><button class="text-link" data-date="${m.date}">${esc(fmtDate(m.date))}</button></td><td>${m.weight}</td><td>${m.waist??'—'}</td><td><button class="icon-btn" data-action="delete-measure" data-date-id="${m.date}" aria-label="Удалить замер ${m.date}">${ico('close')}</button></td></tr>`).join('')}</tbody></table>`:'<p class="long-note" style="margin-top:15px">Записей пока нет. График начнётся с первого сохранённого замера.</p>'}</section><section class="card"><h3>История зала</h3>${Object.values(state.completed).length?Object.values(state.completed).sort((a,b)=>b.date.localeCompare(a.date)).map(c=>`<div class="history-item"><strong>${esc(fmtDate(c.date))} · Фуллбоди ${esc(c.workout)}</strong><br><span class="muted">${c.sets} рабочих подходов · ${esc(CLUBS[c.club]||'Зал')}${c.cardio?` · кардио ${c.cardio} мин`:''}</span></div>`).join(''):'<p class="long-note" style="margin-top:15px">После занятия нажми «Сохранить тренировку». Здесь появятся фактически выполненные подходы.</p>'}</section></div>`}
const CHAPTERS=[
['Твои стартовые ориентиры','Личные параметры задаются в профиле и сохраняются только в браузере. Базовая схема: 2000 ккал, белок 160 г, жиры 65 г, углеводы около 194 г. Это стартовый ориентир для настройки по динамике, а не измеренный обмен веществ.'],
['Почему 2000 ккал и когда пересматривать','Энергетические потребности зависят от массы, роста, возраста и активности. 2000 ккал — пробная точка, которая может оказаться дефицитом или поддержанием. Оценивай её по динамике за 2–3 недели. Если устойчиво падают рабочие веса, сон и самочувствие, подумай о прибавке 100–200 ккал, а не о дополнительном кардио.'],
['Темп снижения и недельное среднее','После первых 1–2 недель рабочий диапазон примерно 0,3–0,7 кг в неделю. Первые изменения могут отражать воду. Взвешивайся 4–7 раз в неделю, сравнивай средние и талию. Если 2–3 недели масса и талия стоят, сначала проверь масло, напитки, выходные и порции. Меняй только один фактор за раз.'],
['Белок и растительные источники','160 г — около 1,8 г/кг твоей исходной массы. Раздели на 3–4 приёма, без необходимости точного расписания. Считай и растительный белок: не дели его автоматически пополам. Чередуй бобовые, сою, крупы. Протеин удобен, когда обычной еды не хватает, но не обязателен.'],
['Жиры и углеводы','65 г жиров — около 29% энергии стартового рациона. Подойдут масла, орехи, яйца, молочные продукты, рыба. Насыщенные жиры разумно ограничить примерно 22 г на 2000 ккал. Углеводы помогают работе в зале: крупы, картофель, хлеб, фрукты и бобовые. Гликемический индекс отдельного продукта не заменяет учёт порций и качества всего питания.'],
['Клетчатка, вода и сытость','Ориентир клетчатки 25–35 г/день с постепенным увеличением. Ешь разнообразные овощи, фрукты, цельные крупы и бобовые. ВОЗ рекомендует минимум 400 г овощей и фруктов и 25 г клетчатки для взрослых. 2–2,5 л напитков — только удобный старт с поправкой на жажду, жару и медицинские ограничения.'],
['Сырой и готовый вес','Вес должен совпадать с записью в базе. В этом меню мясо и рыба сырые, крупы сухие, фасоль готовая. Вода меняет массу блюда, но не добавляет калорий. Для общего рецепта: посчитай калории всех ингредиентов, взвесь итог блюда и раздели калории на его готовую массу. Масло, соусы, напитки и перекусы тоже учитываются.'],
['Магазин, масло и готовка','Надписи «фитнес» и «без сахара» не гарантируют низкую калорийность. Сравни белок, жиры и порцию. Для готовки удобны духовка, аэрогриль, тушение и мультиварка. Масло 5 г ≈45 ккал, 10 г ≈90 ккал. Спрей экономит калории, только если ты используешь меньше масла. Быстро охлаждай готовую еду, храни порции в холодильнике, излишки замораживай.'],
['Питание в день фуллбоди','За 1–3 часа — привычная еда с белком и углеводами. Если времени мало — небольшой переносимый перекус. После зала подойдёт обычный обед или ужин в ближайшие часы. Срочно пить сахар не нужно. Переноси приёмы пищи, сохраняя суточный план. «Сожжённые» калории часов не добавляем автоматически.'],
['Твои залы и оборудование','Назови два зала в профиле. Программа хранит рабочие веса отдельно для каждого. Варианты упражнений — типы тренажёров для подбора в зале. Не переноси килограммы механически между разными моделями. Попроси тренера показать подходящие аналоги и настройки.'],
['Прогрессия в тренажёрах','Первые 2 недели по 2 рабочих подхода, запас 3–4 повтора. Затем по плану, обычно с запасом 2–3. Когда два занятия подряд достигаешь верхней границы повторений с техникой и без симптомов, можно попробовать минимальную прибавку. На дефиците сохранение силы уже хороший результат. Вес на разных моделях тренажёров напрямую не сравнивай.'],
['Здоровье и безопасная нагрузка','Уточни индивидуальные ограничения при заболеваниях и после травм у врача, а настройку тренажёров — с тренером. Не задерживай дыхание, не делай рывков и не работай через боль или головокружение. При внезапных выраженных неврологических симптомах нужна срочная медицинская помощь. Личные медицинские заметки можно записать в профиле: они останутся на твоём устройстве.'],
['Витамины и спортивные добавки','Сначала полноценная еда. Железо и высокие дозы витамина D без показаний не назначаем. Анализы подбирают по симптомам и рискам, а не всем подряд. Креатин моногидрат 3–5 г/день может помогать силовой работе, но не обязателен и способен увеличить массу из-за воды в мышцах. При болезнях почек и лекарственной терапии добавки обсуждают с врачом. BCAA при достаточном белке обычно не нужны.'],
['Кофеин, соль и алкоголь','Для здоровых взрослых EFSA указывает до 200 мг кофеина разово и до 400 мг за день как обычно не вызывающие опасений количества. Это не обязательная доза. Оцени сон и переносимость. Ориентир ВОЗ по соли — менее 5 г за сутки из всех продуктов. У алкоголя нет безрискового уровня для здоровья, он добавляет калории и может мешать сну и аппетиту. Не голодай ради алкоголя и не компенсируй застолье наказанием в зале.'],
['Любимая еда и поддержание','Примерно 80–90% рациона удобно строить на продуктах, дающих белок, клетчатку и нутриенты. Остальное можно оставить любимой еде, учитывая калории. Если дефицит становится трудно переносить, 1–2 недели на текущем поддержании могут помочь с соблюдением. Это не обязательный «разгон метаболизма». Вес на перерыве способен вырасти из-за воды и гликогена.'],
['Что будет после этапа снижения','Не нужно заранее назначать идеальную конечную массу по одному росту. После снижения примерно на 4–5 кг оцени талию, силы, внешний вид и самочувствие. Для будущего набора сначала найди поддержание на новом весе, затем при необходимости небольшой профицит. Рост общей массы и прирост чистых мышц — разные показатели.'],
['Хранение данных на телефоне','Записи хранятся только в браузере на этом устройстве. Другой браузер, приватный режим или удаление данных сайта могут лишить тебя истории. Регулярно экспортируй резервную копию в профиле. На другом устройстве её можно импортировать. Автоматической облачной синхронизации нет. Чтобы быстро открывать сайт, используй «На экран Домой» в меню браузера.']
];
function guide(){return head('Твоя инструкция','Короткие ответы по питанию, тренировкам и восстановлению.',false)+`<div class="guide">${CHAPTERS.map(([title,body],i)=>`<details><summary><span>${String(i+1).padStart(2,'0')} / ${title}</span></summary><p>${body}</p></details>`).join('')}</div><section class="card source-list" style="margin-top:25px"><h3>Источники рекомендаций</h3>${DATA.sources.map(([n,u])=>`<a href="${esc(u)}" target="_blank" rel="noopener">${esc(n)} ↗</a>`).join('')}<p class="long-note">Меню основано на типовых значениях пищевой ценности. Структура тренировки — общий вариант для умеренной силовой нагрузки с учётом заявленного графика, а не медицинское назначение. Фото: Unsplash, иллюстрация питания.</p></section>`}
function settings(){const p=state.profile;return head('Твой профиль','Исходные параметры, удобный график и резервная копия.',false)+`<form id="profile-form"><div class="grid two"><div><section class="card setting-card"><h3>Параметры и питание</h3><div class="setting-grid"><label>Возраст, лет<input name="age" type="number" min="18" max="90" required value="${p.age}"></label><label>Рост, см<input name="height" type="number" min="130" max="230" required value="${p.height}"></label><label>Исходная масса, кг<input name="baseline" type="number" min="35" max="250" step=".1" required value="${p.baseline}"></label><label>Дата начала программы<input name="start" type="date" required value="${esc(p.start)}"></label><label>Калории в день<input name="kcal" type="number" min="1600" max="4000" step="50" required value="${p.kcal}"></label><label>Белок, г<input name="protein" type="number" min="80" max="240" step="5" required value="${p.protein}"></label><label>Жиры, г<input name="fat" type="number" min="45" max="140" step="5" required value="${p.fat}"></label><label>Ориентир шагов<input name="steps" type="number" min="0" max="25000" step="500" required value="${p.steps}"></label><label>Напитки, мл<input name="water" type="number" min="500" max="4000" step="250" required value="${p.water}"></label></div><p class="field-note">Изменение калорий меняет ориентиры дневника, а не порции меню. Порции редактируются в питании. Историю массы записывай в «Прогрессе». Калории не меняются автоматически.</p></section><section class="card setting-card"><h3>Твои дни зала</h3><div class="setting-grid"><label>Название первого зала<input name="club1Name" maxlength="80" value="${esc(state.profile.clubNames?.club1||'Зал 1')}"></label><label>Название второго зала<input name="club2Name" maxlength="80" value="${esc(state.profile.clubNames?.club2||'Зал 2')}"></label></div><div class="setting-grid" style="margin-top:15px">${['A','B'].map((a,i)=>`<label>Фуллбоди ${a}<select name="day${a}">${['Понедельник','Вторник','Среда','Четверг','Пятница','Суббота','Воскресенье'].map((d,j)=>`<option value="${j}" ${Number(p['day'+a])===j?'selected':''}>${d}</option>`).join('')}</select></label>`).join('')}</div><p class="field-note">По умолчанию среда и суббота. Между силовыми желательно оставлять хотя бы день восстановления. Субботу можно заменить воскресеньем.</p></section></div><div><section class="card setting-card"><h3>Питание и здоровье</h3><label>Аллергии, непереносимости, нелюбимые продукты<textarea name="foodsNote" rows="3" maxlength="1000">${esc(p.foodsNote)}</textarea></label><label style="margin-top:14px">Самочувствие и ограничения<textarea name="notes" rows="5" maxlength="2000">${esc(p.notes)}</textarea></label><p class="field-note">Это твои заметки. Сайт не анализирует их автоматически и не исключает продукты из меню. Используй замену блюда и проверяй состав.</p></section><button class="btn" type="submit" style="width:100%">${ico('check')}Сохранить профиль</button><section class="card setting-card" style="margin-top:18px"><h3>Твоя история под контролем</h3><p class="long-note">Записи остаются в этом браузере. Экспорт включает профиль, замеры, блюда и тренировки. Для переноса на другой телефон сохрани файл и импортируй его там.</p><div class="flex wrap" style="margin-top:18px"><button type="button" class="btn soft small" data-action="export">${ico('download')}Резервная копия</button><button type="button" class="btn outline small" data-action="import">Восстановить</button></div><input type="file" id="import-file" accept="application/json,.json" class="hide"><p class="field-note">Экспортируй копию регулярно. Удаление данных браузера удалит локальную историю.</p></section></div></div></form>`}
function render(scroll=false){Object.assign(CLUBS,state.profile.clubNames||{});const opened=[...root.querySelectorAll('details[open][data-ex-detail]')].map(d=>d.dataset.exDetail);nav();root.innerHTML=({home,meals,training,progress,guide,settings}[view]||home)();if(view==='training'){opened.forEach(id=>root.querySelector(`[data-ex-detail="${id}"]`)?.setAttribute('open',''));updateTimer()}if(scroll)window.scrollTo({top:0,behavior:'instant'})}
function go(v){if(!['home','meals','training','progress','guide','settings'].includes(v))return;view=v;if(v==='training')workout=trainingDay()||workout;render(true);location.hash=v}
function chooseDate(d){if(!validDate(d))return;selected=d;workout=trainingDay()||workout;render()}
function validDate(s){return typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&!Number.isNaN(dateObj(s).getTime())&&localDate(dateObj(s))===s}
function dialog(title,body){modal.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Закрыть">${ico('close')}</button></div>${body}`;modal.showModal()}
function swap(slot){dialog('Замена '+['завтрака','обеда','перекуса','ужина'][slot],`<p class="long-note">Выбери вариант. Меняется только этот приём выбранного дня. Отметка «съедено» сохранится.</p>${DATA.recipes.filter(r=>r.type===mealFor(slot).type).map(r=>{let m=macros(r.foods);return `<button class="choice" data-action="select-recipe" data-slot="${slot}" data-id="${r.id}"><strong>${esc(r.name)}</strong><span>≈${round(m[0])} ккал · Б ${round(m[1])} г · ${r.foods.map(([f])=>esc(f.split(',')[0])).join(', ')}</span></button>`}).join('')}`)}
function shopping(){let first=shift(selected,-dayIndex(selected)),tot={};for(let i=0;i<7;i++)for(let j=0;j<4;j++)for(let [f,g]of mealFor(j,shift(first,i)).foods)tot[f]=(tot[f]||0)+g;dialog('Покупки на неделю',`<p class="long-note">${esc(fmtDate(first))} — ${esc(fmtDate(shift(first,6)))}. По меню и изменённым порциям этой недели. Округли до удобных упаковок. Собственные дополнительные блюда не включены.</p><div style="margin-top:15px">${Object.entries(tot).map(([f,g])=>`<label class="shopping-row"><input type="checkbox" data-shopping="${esc(f)}" data-week="${first}" ${state.shopping[first+'-'+f]?'checked':''}><span>${esc(f)}</span><b>${g>=1000?num(g/1000,2)+' кг':round(g)+' г'}</b></label>`).join('')}</div>`)}
function customDialog(){dialog('Дополнительная еда',`<form id="custom-form"><label>Название<input name="name" required maxlength="100" placeholder="Например, мороженое"></label><div class="setting-grid" style="margin-top:15px"><label>Калории<input type="number" name="kcal" min="1" max="5000" required inputmode="numeric"></label><label>Белок, г<input type="number" name="p" min="0" max="300" step=".1" value="0" required inputmode="decimal"></label><label>Жиры, г<input type="number" name="f" min="0" max="300" step=".1" value="0" required inputmode="decimal"></label><label>Углеводы, г<input type="number" name="c" min="0" max="500" step=".1" value="0" required inputmode="decimal"></label></div><p class="field-note">На съеденную порцию, а не на 100 г. Возьми значения с упаковки. Запись сразу добавится к съеденному за день.</p><button class="btn" type="submit" style="width:100%">Добавить в дневник</button></form>`)}
function timerStart(seconds){timerEnd=Date.now()+seconds*1000;try{localStorage.setItem(KEY+'-timer',String(timerEnd))}catch{}updateTimer();if(!timerInterval)timerInterval=setInterval(updateTimer,500)}
function updateTimer(){const el=document.getElementById('timer-value');let t=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));if(el)el.textContent=String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0');if(timerEnd&&t===0){timerEnd=0;try{localStorage.removeItem(KEY+'-timer')}catch{}toast('Отдых закончен. Начинай следующий подход, когда готов.');if(timerInterval){clearInterval(timerInterval);timerInterval=null}}}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='forma-backup-'+TODAY+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Резервная копия готова')}
function validateBackup(x){if(!x||x.version!==1||!x.profile||!Array.isArray(x.measurements)||!x.days||typeof x.days!=='object')throw Error('Это не резервная копия ФОРМЫ');let o=structuredClone(defaults);let p=x.profile;for(let [k,a,b]of [['age',18,90],['height',130,230],['baseline',35,250],['kcal',1600,4000],['protein',80,240],['fat',45,140],['steps',0,25000],['water',500,4000],['dayA',0,6],['dayB',0,6]]){if(['age','height','baseline'].includes(k)&&p[k]===''){o.profile[k]='';continue}if(!Number.isFinite(p[k])||p[k]<a||p[k]>b)throw Error('Некорректный профиль');o.profile[k]=p[k]}if(!validDate(p.start))throw Error('Некорректная дата');o.profile.clubNames={club1:String(p.clubNames?.club1||'Зал 1').slice(0,80),club2:String(p.clubNames?.club2||'Зал 2').slice(0,80)};o.profile.start=p.start;o.profile.club=['club1','club2'].includes(p.club)?p.club:'club1';o.profile.notes=String(p.notes||'').slice(0,2000);o.profile.foodsNote=String(p.foodsNote||'').slice(0,1000);o.measurements=x.measurements.filter(m=>validDate(m.date)&&Number.isFinite(m.weight)&&m.weight>=35&&m.weight<=250).map(m=>({date:m.date,weight:m.weight,waist:Number.isFinite(m.waist)?m.waist:null,sleep:Number.isFinite(m.sleep)?m.sleep:null,note:String(m.note||'').slice(0,600)}));for(let [dt,d]of Object.entries(x.days)){if(!validDate(dt)||!d||typeof d!=='object')continue;let dd={meals:{},sets:{},water:clamp(Number(d.water)||0,0,10000),steps:clamp(Number(d.steps)||0,0,100000),cardio:clamp(Number(d.cardio)||0,0,180),custom:[],variants:{},club:['club1','club2'].includes(d.club)?d.club:'club1'};for(let i=0;i<4;i++){const m=d.meals?.[i];if(m&&recipe(m.id)){dd.meals[i]={id:m.id,done:!!m.done};if(Array.isArray(m.grams))dd.meals[i].grams=recipe(m.id).foods.map(([,g],j)=>Number.isFinite(m.grams[j])?clamp(m.grams[j],0,2000):g)}}for(let [k,v]of Object.entries(d.sets||{})){if(!/^[AB]-(?:(?:club1|club2)-)?(legpress|chest|row|legcurl|lateral|biceps|triceps|pulldown|pec)$/.test(k)||!Array.isArray(v))continue;dd.sets[k]=v.slice(0,5).map(s=>({kg:s.kg===''?'':clamp(Number(s.kg)||0,0,1000),reps:s.reps===''?'':clamp(Number(s.reps)||0,0,100),rir:s.rir===''?'':clamp(Number(s.rir)||0,0,10),done:!!s.done}))}dd.custom=(Array.isArray(d.custom)?d.custom:[]).slice(0,50).map(c=>({name:String(c.name||'Еда').slice(0,100),kcal:clamp(Number(c.kcal)||0,0,5000),p:clamp(Number(c.p)||0,0,300),f:clamp(Number(c.f)||0,0,300),c:clamp(Number(c.c)||0,0,500)}));for(let [k,v]of Object.entries(d.variants||{})){if(/^[AB]-(?:(?:club1|club2)-)?[a-z]+$/.test(k))dd.variants[k]=String(v).slice(0,150)}o.days[dt]=dd}for(let [k,c]of Object.entries(x.completed||{})){if(validDate(c.date)&&['A','B'].includes(c.workout))o.completed[c.date+'-'+c.workout+'-'+(['club1','club2'].includes(c.club)?c.club:'club1')]={date:c.date,workout:c.workout,club:['club1','club2'].includes(c.club)?c.club:'club1',sets:clamp(Number(c.sets)||0,0,50),cardio:clamp(Number(c.cardio)||0,0,180)}}for(let [k,v]of Object.entries(x.shopping||{})){if(k.length<200&&/^\d{4}-\d{2}-\d{2}-/.test(k))o.shopping[k]=!!v}return o}
function syncCompleted(){let key=completedKey();if(state.completed[key])state.completed[key].sets=ROUTINES[workout].reduce((n,id)=>n+(day().sets[setKey(id)]||[]).filter(s=>s.done).length,0)}
document.addEventListener('click',ev=>{const el=ev.target.closest('button,a,[data-date]');if(!el)return;if(el.dataset.nav){go(el.dataset.nav);return}if(el.dataset.date){chooseDate(el.dataset.date);return}if(el.dataset.workout){workout=el.dataset.workout;render();return}const a=el.dataset.action;if(!a)return;switch(a){case'date-prev':chooseDate(shift(selected,-1));break;case'date-next':chooseDate(shift(selected,1));break;case'toggle-meal':{let i=Number(el.dataset.slot),r=mealFor(i);day().meals[i]||={id:r.id};day().meals[i].done=!day().meals[i].done;save();render();break}case'save-steps':{let n=Number(document.getElementById('daily-steps').value);if(!Number.isFinite(n)||n<0||n>100000){toast('Введи шаги от 0 до 100 000');return}day().steps=round(n);save();toast('Шаги сохранены');break}case'water':day().water=clamp(day().water+Number(el.dataset.add),0,10000);save();render();break;case'swap':swap(Number(el.dataset.slot));break;case'select-recipe':{let i=Number(el.dataset.slot);day().meals[i]={id:el.dataset.id,done:!!day().meals[i]?.done};save();modal.close();render();toast('Блюдо заменено');break}case'shopping':shopping();break;case'custom-meal':customDialog();break;case'close-modal':modal.close();break;case'remove-custom':day().custom.splice(Number(el.dataset.index),1);save();render();break;case'timer':timerStart(Number(el.dataset.seconds));break;case'timer-stop':timerEnd=0;try{localStorage.removeItem(KEY+'-timer')}catch{}updateTimer();break;case'set-done':{let id=el.dataset.ex,i=Number(el.dataset.index),s=setData(id,i);if(!s.done&&(!Number.isFinite(Number(s.kg))||s.kg===''||!Number.isFinite(Number(s.reps))||Number(s.reps)<=0)){toast('Сначала запиши вес и повторения');return}s.done=!s.done;syncCompleted();save();render();if(s.done)timerStart(EXERCISES[id].rest);break}case'finish-workout':{let n=ROUTINES[workout].reduce((n,id)=>n+(day().sets[setKey(id)]||[]).filter(s=>s.done).length,0);if(!n){toast('Отметь хотя бы один выполненный подход');return}let cardio=Number(document.getElementById('cardio-minutes').value)||0;if(cardio<0||cardio>180){toast('Проверь длительность кардио');return}day().cardio=cardio;state.completed[completedKey()]={date:selected,workout,club:club(),sets:n,cardio};save();render();toast('Тренировка сохранена в истории');break}case'delete-measure':dialog('Удалить замер?',`<p>Запись за ${esc(fmtDate(el.dataset.dateId))} будет удалена.</p><button class="btn danger" data-action="confirm-delete-measure" data-date-id="${el.dataset.dateId}" style="margin-top:20px">Удалить запись</button>`);break;case'confirm-delete-measure':state.measurements=state.measurements.filter(m=>m.date!==el.dataset.dateId);save();modal.close();render();break;case'export':exportData();break;case'import':document.getElementById('import-file').click();break;case'confirm-import':if(window.pendingImport){state=window.pendingImport;delete window.pendingImport;save();modal.close();render();toast('История восстановлена')}break}});
document.addEventListener('change',async ev=>{let e=ev.target;if(e.id==='training-club'){day().club=e.value;state.profile.club=e.value;save();render();return}if(e.id==='selected-date'){chooseDate(e.value);return}if(e.dataset.portion!==undefined){let n=Number(e.value);if(!Number.isFinite(n)||n<0||n>2000){toast('Порция: от 0 до 2000 г');render();return}let i=Number(e.dataset.portion),r=mealFor(i);day().meals[i]||={id:r.id};day().meals[i].grams=r.foods.map(([,g])=>g);day().meals[i].grams[Number(e.dataset.food)]=n;save();render();return}if(e.dataset.set){let s=setData(e.dataset.set,Number(e.dataset.i)),n=e.value===''?'':Number(e.value),f=e.dataset.field,max=f==='kg'?1000:f==='reps'?100:10;if(n!==''&&(!Number.isFinite(n)||n<0||n>max)){toast('Проверь значение подхода');e.value=s[f];return}s[f]=n;save();return}if(e.dataset.variant){day().variants||={};day().variants[setKey(e.dataset.variant)]=e.value;save();return}if(e.dataset.shopping){state.shopping[e.dataset.week+'-'+e.dataset.shopping]=e.checked;save();return}if(e.id==='cardio-minutes'){let n=Number(e.value);if(Number.isFinite(n)&&n>=0&&n<=180){day().cardio=n;save()}return}if(e.id==='import-file'&&e.files[0]){try{let f=e.files[0];if(f.size>5e6)throw Error('Файл слишком большой');let imported=validateBackup(JSON.parse(await f.text()));window.pendingImport=imported;dialog('Восстановить историю?',`<p class="long-note">В копии: ${imported.measurements.length} замеров и ${Object.keys(imported.completed).length} тренировок. Она заменит текущие записи в этом браузере. Перед заменой можно закрыть окно и экспортировать текущую историю.</p><button class="btn" style="margin-top:20px" data-action="confirm-import">Заменить данными из копии</button>`)}catch(err){toast(err.message||'Не удалось прочитать копию')}e.value=''}});
document.addEventListener('submit',ev=>{ev.preventDefault();let form=ev.target,f=new FormData(form);if(form.id==='custom-form'){day().custom||=[];day().custom.push({name:String(f.get('name')).trim(),kcal:Number(f.get('kcal')),p:Number(f.get('p')),f:Number(f.get('f')),c:Number(f.get('c'))});save();modal.close();render();toast('Еда добавлена');return}if(form.id==='measure-form'){let m={date:selected,weight:Number(f.get('weight')),waist:f.get('waist')?Number(f.get('waist')):null,sleep:f.get('sleep')?Number(f.get('sleep')):null,note:String(f.get('note')).trim()};if(m.weight<35||m.weight>250)return;state.measurements=state.measurements.filter(x=>x.date!==selected);state.measurements.push(m);save();render();toast('Замер сохранён');return}if(form.id==='profile-form'){let p={...state.profile};for(let k of ['age','height','baseline','kcal','protein','fat','steps','water','dayA','dayB'])p[k]=Number(f.get(k));p.clubNames={club1:String(f.get('club1Name')||'Зал 1').slice(0,80),club2:String(f.get('club2Name')||'Зал 2').slice(0,80)};p.start=String(f.get('start'));p.notes=String(f.get('notes'));p.foodsNote=String(f.get('foodsNote'));let gap=Math.abs(p.dayA-p.dayB);if(gap===0||gap===1||gap===6){toast('Выбери дни с хотя бы одним днём отдыха между ними');return}if(p.protein*4+p.fat*9>p.kcal-200){toast('Слишком мало калорий остаётся на углеводы. Проверь БЖУ.');return}state.profile=p;save();render();toast('Профиль сохранён. Порции меню не менялись.')}});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});
window.addEventListener('hashchange',()=>{let v=location.hash.slice(1);if(['home','meals','training','progress','guide','settings'].includes(v)&&v!==view){view=v;render(true)}});
fetch('data.json').then(r=>{if(!r.ok)throw Error('Данные недоступны');return r.json()}).then(d=>{DATA=d;view=['home','meals','training','progress','guide','settings'].includes(location.hash.slice(1))?location.hash.slice(1):'home';workout=trainingDay()||'A';render();if(timerEnd>Date.now())timerInterval=setInterval(updateTimer,500)}).catch(()=>{root.innerHTML='<div class="empty"><h2>Не удалось загрузить программу</h2><p>Проверь соединение и обнови страницу. Сохранённая история остаётся в браузере.</p><button class="btn" onclick="location.reload()" style="margin-top:20px">Обновить</button></div>'});
// Save edits on input as well as change: mobile keyboards may navigate before blur.
document.addEventListener('input',ev=>{const e=ev.target;if(!DATA)return;if(e.dataset.portion!==undefined){const n=Number(e.value);if(e.value===''||!Number.isFinite(n)||n<0||n>2000)return;const i=Number(e.dataset.portion),r=mealFor(i);day().meals[i]||={id:r.id};day().meals[i].grams=r.foods.map(([,g])=>g);day().meals[i].grams[Number(e.dataset.food)]=n;save();let card=e.closest('.meal-card'),m=macros(mealFor(i).foods);if(card)card.querySelector('.macro-mini').textContent=`≈${round(m[0])} ккал · Б ${round(m[1])} · Ж ${round(m[2])} · У ${round(m[3])} г`;let t=planned(),total=root.querySelector('.nutrition-total strong');if(total)total.innerHTML=round(t[0])+' <span>ккал</span>';let span=root.querySelector('.nutrition-total > span');if(span)span.innerHTML=`<b>Б ${round(t[1])}</b> / Ж ${round(t[2])} / У ${round(t[3])} г`}if(e.dataset.set){let f=e.dataset.field,n=e.value===''?'':Number(e.value),max=f==='kg'?1000:f==='reps'?100:10;if(n===''||(Number.isFinite(n)&&n>=0&&n<=max)){setData(e.dataset.set,Number(e.dataset.i))[f]=n;save()}}});
